  "stuSess.penaltyChoiceRefund": "元の支払方法に返金",
  "stuSess.penaltyChoiceRefundDesc": "返金（€{amount}）をご希望の場合はinfo@tutlio.ltまでお問い合わせください。カードで支払った場合は、Stripeを通じて自動で返金手続きが始まることもあります。",
  "stuSess.creditAvailable": "利用可能なクレジット",
  "stuSess.payWithCredit": "クレジットで支払う",
  "stuSess.creditAppliedSuccess": "クレジット残高に€{amount}が追加されました。次回のレッスンに自動で充当されます。",
  "stuSess.refundContactNote": "返金をご希望の場合は、<a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>までお問い合わせください。",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">ご質問やお困りのことは、<a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>までお問い合わせください。</p><p class=\"font-semibold text-emerald-900\">Stripeを通じて返金手続きを開始しました。</p><p class=\"text-emerald-800 mt-1\">カードへの返金には通常<strong>5–10営業日</strong>ほどかかります（金融機関によって異なります）。通常の期間を過ぎても返金されない場合は、<a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>までメールでお問い合わせください。</p>",
  "stuSess.refundSuccessManualTutor": "<p>このレッスンは、TutlioのStripe決済以外（銀行振込や現金など）で支払われたと思われます。ここでは自動返金は行われません。</p><p class=\"mt-2\">返金については、担当講師の<strong>{tutor}</strong>にお問い合わせください。予約情報に記載された連絡先、または講師から直接案内された連絡先をご利用ください。</p>",
  "stuSess.refundSuccessManualOrg": "<p>このレッスンは、TutlioのStripe決済以外（銀行振込や現金など）で支払われたと思われます。ここでは自動返金は行われません。</p><p class=\"mt-2\">組織を通じて受講しているため、<strong>組織の管理者</strong>にお問い合わせください（講師を通じて、または組織が公開している連絡先から）。</p>",
  "stuSess.refundTutorFallback": "担当講師",
