  "landing.footerResources": "お役立ち情報",
  "landing.faq.whatIsQ": "Tutlioとは？",
  "landing.faq.whatIsA": "Tutlioは、個人講師や個別指導教室のための運営管理プラットフォームです。予定、支払い、受講者との連絡、レッスンの記録を一か所で管理できます。",
  "landing.faq.whoForQ": "どのような方に向いていますか？",
  "landing.faq.whoForA": "個人講師、音楽講師、語学講師、数学講師、個別指導教室、教育センターなど、規模を問わずご利用いただけます。",
  "landing.faq.waitlistQ": "受講者のキャンセル待ちはどのように動きますか？",
  "landing.faq.waitlistA": "受講者がレッスンをキャンセルすると、空いた時間枠をキャンセル待ちの受講者に自動で案内します。最初に確定した受講者が予約できるため、キャンセルによる収入の機会損失を防ぎます。",
  "landing.faq.freeTrialQ": "無料トライアルはありますか？",
  "landing.faq.freeTrialA": "はい。新規アカウントには自動で7日間の無料トライアルが適用されます。コードは不要です。期間中の請求はなく、いつでも解約できます。",
  "landing.faq.languagesQ": "対応言語を教えてください",
  "landing.faq.languagesA": "Tutlioは{count}言語に対応しています：{languages}。",
  "landing.faqTitle": "よくあるご質問",
  "landing.feature.digital-business-card": "デジタル名刺",
  "landing.feature.digital-business-cardDesc": "自己紹介、最新の料金、空き時間を載せた専用ページを共有できます。受講者はその場でレッスンをリクエストできます。",
  "featuresIndex.newBadge": "新機能",
  "feature.digital-business-card.pageTitle": "興味をレッスンのリクエストにつなげるデジタル名刺",
  "feature.digital-business-card.pageDesc": "自己紹介、レッスン、料金、口コミ、最新の空き時間をひとつの見やすいページに。受講希望者はその場で科目と時間を選べるため、長いメッセージのやり取りで問い合わせを取りこぼしません。",
  "feature.digital-business-card.detailsTitle": "受講を決めるために必要な情報をすべて掲載",
  "feature.digital-business-card.oneLink": "個別指導事業を紹介するひとつのリンク",
  "feature.digital-business-card.oneLinkDesc": "SNSのプロフィール、料金表、予約のやり取りをひとつのページにまとめ、どこでも共有できます。",
  "feature.digital-business-card.liveAvailability": "常に最新の空き時間",
  "feature.digital-business-card.liveAvailabilityDesc": "Tutlioのカレンダーから空き時間を直接表示するため、実際に指導可能な時間だけがリクエストされます。",
  "feature.digital-business-card.instantEnquiries": "指導中にもレッスンのリクエストを受付",
  "feature.digital-business-card.instantEnquiriesDesc": "保護者や受講者が科目、形式、時間を選び、連絡先を入力します。日程調整のやり取りなしで、必要な情報が揃ったリクエストを受け取れます。",
  "feature.digital-business-card.professionalBrand": "信頼感のある第一印象",
  "feature.digital-business-card.professionalBrandDesc": "写真、指導方針、科目、料金、確認済みの口コミ、ブランドカラーを掲載。スマートフォンでも見やすいページです。",
  "feature.digital-business-card.faq.whatShowsQ": "デジタル名刺には何を掲載できますか？",
  "feature.digital-business-card.faq.whatShowsA": "自己紹介、科目、レッスン形式、公開料金、カレンダーの空き枠、所在地、使用言語、SNSリンク、確認済みの受講者の口コミを掲載できます。",
  "feature.digital-business-card.faq.howBookingWorksQ": "送信した時点でレッスンの予約が確定しますか？",
  "feature.digital-business-card.faq.howBookingWorksA": "受講希望者が科目と空き時間を選び、必要事項を入力して予約リクエストを送信します。Tutlioで受け取った後、新しい受講者を確認してから予定に追加できます。",
  "feature.digital-business-card.faq.whereShareQ": "どこでページを共有するとよいですか？",
  "feature.digital-business-card.faq.whereShareA": "Instagram、TikTok、Facebookグループ、広告、メールの署名、メッセージ、QRコードなどで共有できます。料金や予定が変わっても、同じリンクで最新情報を表示できます。",
  "feature.digital-business-card.demo.eyebrow": "受講希望者向け画面の操作デモ",
