  "enterpriseSuccess.backHome": "ホームページに戻る",
  "landing.leadSuccess": "ありがとうございます。担当者からご連絡します。",
  "orgTutorPolicy.title": "講師向け内部規定",
  "orgTutorPolicy.intro": "プラットフォームを利用する前に、組織の内部規定をご確認ください。",
  "orgTutorPolicy.acceptBtn": "確認しました",
  "orgTutorPolicy.viewBtn": "内部規定を見る",
  "orgTutorPolicy.s1Title": "1. 総則",
  "orgTutorPolicy.s1Body": "本規定は、教員または講師（以下「講師」）によるTutlioプラットフォーム（以下「本プラットフォーム」）の利用を定めるものです。講師は、所属する教育事業者、学校、または個別指導センター（以下「組織」）から本プラットフォームに招待されています。本プラットフォームの技術的な保守とサポートはMB Tutlioが行います。アカウントの利用により、本規定およびプライバシーポリシーに同意したものとします。",
  "orgTutorPolicy.s2Title": "2. アカウントと予定の管理",
  "orgTutorPolicy.s2Intro": "本プラットフォームは、講師が受講者との日程調整に時間を費やさずに済むよう設計されています。",
  "orgTutorPolicy.s2Link": "専用リンク：担当科目に基づく個別のレッスン予約リンクが割り当てられます。受講者はこのリンクで予約します。",
  "orgTutorPolicy.s2Calendar": "カレンダーの同期：空き時間はGoogle Calendarとの連携（2方向同期）に直接依存します。カレンダーに表示される空き時間を正確かつ最新の状態に保つ責任は講師にあります。予定ありと表示された時間を受講者が予約することはできません。",
  "orgTutorPolicy.s2Security": "アカウントの安全管理：アカウントは個人専用です。ログイン情報を安全に保管し、第三者と共有してはなりません。",
  "orgTutorPolicy.s3Title": "3. レッスンのキャンセルとキャンセル待ち",
  "orgTutorPolicy.s3Intro": "本プラットフォームは、指導時間を最大限に活用し、空き枠を減らすために役立ちます。",
  "orgTutorPolicy.s3Auto": "受講者がレッスンをキャンセルすると、キャンセル待ちのほかの受講者に自動で通知（SMS・メール）し、空き枠を案内します。講師による追加の操作は不要です。",
  "orgTutorPolicy.s3Rules": "キャンセル規定（キャンセル可能な期限や、それに伴う取り扱い）は組織が定めます。",
  "orgTutorPolicy.s4Title": "4. 収支と支払い",
  "orgTutorPolicy.s4Intro": "講師が保護者への請求や代金回収を行う必要はありません。",
  "orgTutorPolicy.s4Advance": "受講者または保護者からのレッスン料金はすべて本プラットフォームで事前に回収され、組織に直接送金されます。",
  "orgTutorPolicy.s4Confirmed": "システム上で確定済み（決済済み）となっているレッスンのみを実施してください。",
  "orgTutorPolicy.s4Contact": "報酬、支払日程、そのほか金銭に関する事項は、組織の管理者に直接お問い合わせください。MB Tutlioは講師と直接の金銭取引を行いません。",
  "orgTutorPolicy.s5Title": "5. 受講者データの保護（GDPR）",
  "orgTutorPolicy.s5Intro": "講師は受講者の個人情報、内部メモ、教材にアクセスできます。以下を遵守してください。",
  "orgTutorPolicy.s5Use": "データはレッスンの準備と実施のためにのみ使用すること。",
  "orgTutorPolicy.s5NoCopy": "受講者や保護者の連絡先を、本プラットフォーム外へ複製、エクスポート、配布しないこと。",
  "orgTutorPolicy.s5Notes": "講師と組織の管理者のみに表示され、受講者や保護者には公開されない組織内の記録（学習進捗に関するメモ）を保護すること。",
  "orgTutorPolicy.s5Termination": "組織との業務関係が終了した場合、これらのデータへのアクセス権は直ちに取り消されます。",
  "orgTutorPolicy.s6Title": "6. 技術的運営と責任の制限",
  "orgTutorPolicy.s6Body": "違法な目的での利用、教材内での悪意あるリンクの配布、その他システムの運営を妨げる行為は禁止されています。MB Tutlioは本プラットフォームの運営と技術的保守を行いますが、講師のインターネット接続、端末の故障、Google Calendarの設定不備による障害について責任を負いません。",
  "orgTutorPolicy.s7Title": "7. サポートと連絡先",
  "orgTutorPolicy.s7Org": "レッスンの予定、報酬、受講者の割り当て、業務の進め方に関するご質問は、組織の管理者にお問い合わせください。",
  "orgTutorPolicy.s7Tech": "本プラットフォームの技術的な不具合（カレンダーが同期しない、通知が届かないなど）は、組織の管理者にお知らせください。管理者からTutlioの技術サポートに連絡します。",
  "register.orgPolicyConsent": "本プラットフォームの利用により、以下に同意したものとします：",
