  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "化学・生物講師",
  "quiz.offer.testimonial.solo.copy3": "「公開ページと予約をひとつのリンクにまとめたことで、新しい受講者が早く判断できるようになりました。同じ情報を一人ひとりに送る必要もなくなりました。」",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "物理講師",
  "quiz.offer.testimonial.solo.copy4": "「カレンダーでレッスン、変更、支払い状況をすぐに確認できます。日々の事務作業がずっと短く、わかりやすくなりました。」",
  "quiz.offer.testimonial.company.copy1": "「以前はレッスンの変更、講師のコメント、稼働時間が別々のメッセージで届いていました。今は管理チームがひとつの予定表で全体を把握できます。」",
  "quiz.offer.testimonial.company.name2": "独立系個別指導センター",
  "quiz.offer.testimonial.company.role2": "オーナー · 講師8人",
  "quiz.offer.testimonial.company.copy2": "「以前は金曜の夜にカレンダーと講師のメッセージを照合してから、報酬の支払いを準備していました。Tutlioでは、その確認の大半がすでに済んでいます。」",
  "quiz.offer.testimonial.company.name3": "語学指導スタジオ",
  "quiz.offer.testimonial.company.role3": "運営責任者 · 講師14人",
  "quiz.offer.testimonial.company.copy3": "「レッスンの日時が変わると、チーム全員がすぐ同じ更新を確認できます。確認のメッセージが減り、保護者にもより明確に回答できるようになりました。」",
  "quiz.offer.testimonial.company.name4": "試験対策アカデミー",
  "quiz.offer.testimonial.company.role4": "経理担当者 · 講師22人",
  "quiz.offer.testimonial.company.copy4": "「レッスンの種類によって講師の報酬規定が異なるため、以前は月末に手作業で確認することが多くありました。Tutlioのおかげで、落ち着いて処理できるようになりました。」",
  "quiz.offer.testimonial.school.name2": "独立系コミュニティスクール",
  "quiz.offer.testimonial.school.role2": "入学担当者 · 受講者86人",
  "quiz.offer.testimonial.school.copy2": "「入学の時期は、申込書、保護者情報、署名済み契約書を別々のフォルダーで管理していました。今はご家族ごとの状況をひとつの場所で追えます。」",
