  "landing.custom.title": "働き方に合わせて変わるソフトウェア - その逆ではなく",
  "landing.custom.sub": "スクールもエージェンシーも、運営のしかたは少しずつ違います。標準の流れが合わないときは、Tutlio をお客さまの業務に合わせて調整します - 四半期ではなく、たいてい数週間で。すでにお客さま向けに作った例をご紹介します。",
  "landing.custom.ex1Title": "電子署名つきの年間契約",
  "landing.custom.ex1Desc": "ある私立校は、保護者が年間契約に電子的に署名し、分割で支払い、すべての入金が会計用の書き出しに載ることを求めていました。今ではこの一連の流れが Tutlio 内で完結しています。",
  "landing.custom.ex2Title": "講師報酬と手数料のルール",
  "landing.custom.ex2Desc": "あるエージェンシーは、科目とレッスン種別に応じて講師に報酬を支払い、そこに自社手数料を上乗せしています。そのルールを再現したことで、講師の月次明細と請求書が自動で作られるようになりました。",
  "landing.custom.ex3Title": "保護者がワンクリックで承諾できる案内",
  "landing.custom.ex3Desc": "あるスクールは、追加レッスンをメールで案内し、保護者にワンクリックで承諾してほしいと考えていました - アカウント登録も印刷も不要で。今では承諾、請求、初回レッスンの案内までが自動で進みます。",
  "landing.custom.ex4Title": "自社ブランドを自社サイトで",
  "landing.custom.ex4Desc": "ある団体は、自社のロゴと配色に加え、自社サイトに埋め込んだログインを希望しました。受講者と保護者がサイトを離れたと感じないためです。今では Tutlio が同団体のブランドで動いています。",
  "landing.custom.note": "これらはどれも特別版ではありません。すべてのカスタマイズは、チームがすでに使っているのと同じ製品の一部になり、今後の更新もすべて含まれます。",
