  "compare.note.websiteBuilder": "ウェブサイト作成機能",
  "compare.note.bookingPlugin": "予約プラグイン",
  "compare.note.storefronts": "販売ページとウェブフォーム",
  "compare.note.multipleMethods": "複数の決済手段",
  "compare.note.smsIncluded": "標準で利用可",
  "compare.note.perMessage": "1 通ごとの課金",
  "compare.note.addOn": "オプション",
